```python
# Simple store simulator

# Initialize the store with no products
store = {}

def add_product(name, quantity):
    """Add a product to the store with the given name and quantity."""
    if name not in store:
        store[name] = quantity
        print(f"Product '{name}' added successfully with {quantity} units.")
    else:
        print(f"Product '{name}' already exists in the store with {store[name]} units.")

def remove_product(name, quantity=1):
    """Remove a product from the store with the given name and quantity."""
    if name in store:
        if store[name] >= quantity:
            store[name] -= quantity
            print(f"Product '{name}' removed successfully with {quantity} units.")
        else:
            print(f"Insufficient quantity of product '{name}' to remove. Only {store[name]} units available.")
    else:
        print(f"Product '{name}' not found in the store.")

def view_products():
    """Print all products in the store with their quantities."""
    print("\nCurrent store contents:")
    for product, quantity in store.items():
        print(f"{product}: {quantity} units")

def main():
    while True:
        command = input("\nEnter a command (add, remove, view, or quit): ").lower()

        if command == "add":
            name = input("Enter product name: ").strip()
            quantity = int(input("Enter quantity: "))
            add_product(name, quantity)

        elif command == "remove":
            name = input("Enter product name: ").strip()
            remove_product(name)

        elif command == "view":
            view_products()

        elif command == "quit":
            print("\nGoodbye!")
            break

        else:
            print("Invalid command. Please try again.")

if __name__ == "__main__":
    main()
```

This program allows users to add, remove, and view products in the store. The `add_product` function checks if the product already exists and adds it with the given quantity. The `remove_product` function checks if the product exists and removes it with the given quantity. The `view_products` function prints all products in the store with their quantities.
